∀ (s : Bool × List (Fin 10)),
  NativeBridge.Incremental.NumericWrite.decimalSignedOf s =
    if s.1 = true then Rocq.Corelib.Init.Decimal.signed_int.Neg (NativeBridge.decimalDigitsOf s.2)
    else Rocq.Corelib.Init.Decimal.signed_int.Pos (NativeBridge.decimalDigitsOf s.2)

∀ (s : Bool × List (Fin 16)),
  NativeBridge.Incremental.NumericWrite.hexadecimalSignedOf s =
    if s.1 = true then Rocq.Corelib.Init.Hexadecimal.signed_int.Neg (NativeBridge.hexadecimalDigitsOf s.2)
    else Rocq.Corelib.Init.Hexadecimal.signed_int.Pos (NativeBridge.hexadecimalDigitsOf s.2)
